import * as Fs from "node:fs"
import * as Path from "node:path"
import { publishablePackages } from "./packages.ts"

const check = process.argv.includes("--check")
const stale: Array<string> = []

const declarations = (dir: string, base: string = dir): Array<string> =>
  Fs.readdirSync(dir, { withFileTypes: true }).flatMap((entry) => {
    const file = Path.join(dir, entry.name)
    if (entry.isDirectory()) return entry.name === "internal" ? [] : declarations(file, base)
    return entry.name.endsWith(".d.ts") ? [Path.relative(base, file)] : []
  }).sort()

for (const { dir, manifest } of publishablePackages()) {
  const dist = Path.join(dir, "dist")
  const files = declarations(dist)
  const report = [
    `# API report for \`${manifest.name}\``,
    "",
    "Generated by `pnpm api-snapshot` from the built declarations. Review every change: it is the package's public API.",
    "",
    ...files.flatMap((file: string) => [
      `## ${file}`,
      "",
      "```ts",
      Fs.readFileSync(Path.join(dist, file), "utf8").replace(/\n\/\/# sourceMappingURL=.*\n?$/, "\n").trimEnd(),
      "```",
      ""
    ])
  ].join("\n")
  const target = Path.join(dir, "etc", `${Path.basename(dir)}.api.md`)

  if (check) {
    if (!Fs.existsSync(target) || Fs.readFileSync(target, "utf8") !== report) stale.push(target)
    continue
  }
  Fs.mkdirSync(Path.dirname(target), { recursive: true })
  Fs.writeFileSync(target, report)
  console.log(`api-snapshot: wrote ${Path.relative(process.cwd(), target)}`)
}

if (stale.length > 0) {
  console.error(`api-snapshot: the public API changed; run \`pnpm api-snapshot\` and review:\n${stale.join("\n")}`)
  process.exit(1)
}
if (check) console.log("api-snapshot: up to date")
